mapper.delete:
delete from knowledge_chunk_embedding e
using knowledge_chunk c
where e.chunk_id = c.id and c.document_id = #{documentId}

delete from knowledge_chunk_embedding e
using knowledge_chunk c
where e.chunk_id = c.id
  and c.document_id = #{documentId}
  and e.index_version = #{indexVersion}

mapper.select:
select e.chunk_id, c.document_id, d.title, c.content,
       e.embedding <=> cast(#{queryVector, typeHandler=com.example.aichat.knowledge.mapper.typehandler.PgVectorTypeHandler}
           as vector) as distance
from knowledge_chunk_embedding e
join knowledge_chunk c on c.id = e.chunk_id
join knowledge_document d on d.id = c.document_id
where e.knowledge_base_id = #{knowledgeBaseId}
  and e.embedding_model_id = #{modelId}
  and e.dimension = #{dimension}
  and e.index_version = #{indexVersion}
  and d.deleted = false
order by e.embedding <=> cast(#{queryVector, typeHandler=com.example.aichat.knowledge.mapper.typehandler.PgVectorTypeHandler}
    as vector)
limit #{topK}
